import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
import { ZimmContactIconRow } from 'app/components/ui-kits/molecules/zimmContactIconRow';
import type { FooterNavGroupEntry } from 'app/types/contentful';

const ZIMM_FOOTER_NAV_COLUMN_RECIPE = 'ZimmFooterNavColumn';

// Non-breaking space. Marks a label whose line break is intentional — see the nav item below.
const NBSP = ' ';

/**
 * True when a label carries a deliberate NBSP wrap point (e.g. "Acknowledgement of Country")
 * — see the width:min-content comment below for why this must stay gated rather than applied to
 * every label. Extracted as a named export so the gate itself is unit-testable without asserting
 * on Chakra's `sx`-generated CSS output.
 */
export const hasIntentionalLineBreak = (label: string): boolean => label.includes(NBSP);

type FooterNavColumnProps = {
  group: FooterNavGroupEntry;
  phoneHref?: string;
  whatsAppHref?: string;
  emailHref?: string;
};

/**
 * One footer nav column: heading, link list, and (for the Contact group) the contact-channel
 * icon row. Extracted from Footer's inline JSX — this is where the Figma pixel-precision
 * workarounds below actually live now, rather than being buried in the footer assembly.
 *
 * @param props see FooterNavColumnProps
 */
export const FooterNavColumn = ({ group, phoneHref, whatsAppHref, emailHref }: FooterNavColumnProps) => {
  const styles = useMultiStyleConfig(ZIMM_FOOTER_NAV_COLUMN_RECIPE, {});

  return (
    <chakra.div __css={styles.col}>
      {/* Figma section column: flex-col gap-16px — the column gap replaces marginBottom on the
          heading. Contact heading has 4px left offset. */}
      <chakra.p
        __css={{
          ...styles.heading,
          ...(group.fields.showContactChannels ? { paddingLeft: 'var(--zimm-scale-2xs)' } : {}),
        }}
      >
        {group.fields.heading}
      </chakra.p>
      {/* Figma Links div (2228:19423): flex-col, items-start, width 100%, gap 0.
          DELIBERATE DEVIATION: Figma puts the Contact items at x=0 while indenting only its
          heading 4px (wrapper 40000407:22289) — About and Help headings sit flush at 0, so that
          asymmetry reads as a stray wrapper rather than intent. We indent the Contact items to
          match their heading so the column aligns as a unit. The icon row below needs no
          indent: its 24px box centres a 16px glyph, so the glyph edge already lands at 4px.
          Pending Kiera. */}
      <chakra.ul __css={styles.list}>
        {group.fields.links.map((link) => (
          <chakra.li
            key={link.sys.id}
            __css={{
              ...styles.listItem,
              ...(group.fields.showContactChannels ? { paddingLeft: 'var(--zimm-scale-2xs)' } : {}),
            }}
          >
            {/* Each item h-[24px] items-center, no gap. ZimmNavItem's baseStyle supplies
                minHeight 24px, whiteSpace normal (so the label below can wrap) and uppercase.

                width:min-content only for labels that carry a non-breaking space. A wrapped
                element takes the AVAILABLE width, not its longest line, so without this the
                Acknowledgement item filled the column's 160px cap while its longest line is
                115px — 45px of dead space that pushed the Contact column right, against Figma
                where every column hugs its content. min-content resolves to the widest
                unbreakable run, which the NBSP makes exactly "ACKNOWLEDGEMENT" (115px). It must
                stay gated: applied to a single-line label it collapses to the longest word and
                wraps it ("Book an Appointment" 131px -> 76px, two lines). */}
            <ZimmNavItem
              href={link.fields.href}
              label={link.fields.label}
              inverse
              sx={hasIntentionalLineBreak(link.fields.label) ? { width: 'min-content' } : undefined}
            />
          </chakra.li>
        ))}
        {/* Contact channels are the LAST CHILD OF THE LIST, not a sibling of it — Figma's
            Icon-list (40002081:14616) sits inside Links at y=72, directly after "CONNECT WITH
            US" ends at y=72, so only its own 4px padding-top separates them. Rendered outside
            the <ul> it instead picked up the column's 16px gap and sat 20px low against
            Figma's 4px. */}
        {group.fields.showContactChannels && (
          <chakra.li __css={styles.listItem}>
            <ZimmContactIconRow phoneHref={phoneHref} whatsAppHref={whatsAppHref} emailHref={emailHref} />
          </chakra.li>
        )}
      </chakra.ul>
    </chakra.div>
  );
};

