import { describe, test, expect } from 'vitest';
import { components } from './index';

describe('TEMP PROBE - not part of deliverable', () => {
  test('recipeGuards-style PROP_COMBINATIONS never sets selected:true', () => {
    const DEFAULT_STYLE_PROPS: Record<string, unknown> = {
      inverse: false, disabled: false, hasError: false, focused: false, filled: false,
      theme: {}, colorMode: 'light',
    };
    const booleanKeys = Object.keys(DEFAULT_STYLE_PROPS).filter((k) => typeof DEFAULT_STYLE_PROPS[k] === 'boolean');
    const combos = Array.from({ length: 2 ** booleanKeys.length }, (_, i) => {
      const combo = { ...DEFAULT_STYLE_PROPS };
      booleanKeys.forEach((key, bit) => { combo[key] = Boolean(i & (1 << bit)); });
      return combo;
    });
    const bs = (components as any).ZimmColourSwatch.baseStyle as (p: any) => any;
    const sawSelectedBranch = combos.some((c) => {
      const resolved = bs(c);
      return 'borderBottomWidth' in resolved.swatch;
    });
    console.log('SAW_SELECTED_BRANCH_ACROSS_32_COMBOS:', sawSelectedBranch);
    console.log('COMBOS_COUNT:', combos.length);
    console.log('SELECTED_KEY_PRESENT_IN_ANY_COMBO:', combos.some((c) => 'selected' in c));
    // Direct call with selected explicitly true, to show the branch DOES exist and works:
    const direct = bs({ selected: true });
    console.log('DIRECT_CALL_selected_true_HAS_borderBottomWidth:', 'borderBottomWidth' in direct.swatch);
    expect(true).toBe(true);
  });
});
