mkdir -p /tmp/swatch_probe
cat > /tmp/swatch_probe/test.html << 'EOF'
<!DOCTYPE html>
<html>
<head>
<style>
  :root {
    /* Real, registered zimm token (from zimmTokens.ts line 54) */
    --zimm-color-bg-02: #f6f4f1;
    /* Deliberately NOT defining --zimm-color-background-02 — because it genuinely
       is not defined anywhere in the real zimmTokens.ts registry. This file
       mirrors the real :root exactly as ZimmTokensGlobal would emit it. */
  }
  #control { width: 100px; height: 100px; background-color: var(--zimm-color-bg-02); }
  #actual-recipe-value { width: 100px; height: 100px; background-color: var(--zimm-color-background-02); }
</style>
</head>
<body>
  <div id="control"></div>
  <div id="actual-recipe-value"></div>
</body>
</html>
EOF
cat > /tmp/swatch_probe/probe.mjs << 'EOF'
import { chromium } from 'playwright';
import path from 'node:path';

const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto('file://' + path.resolve('/tmp/swatch_probe/test.html'));

const control = await page.$eval('#control', (el) => getComputedStyle(el).backgroundColor);
const actual = await page.$eval('#actual-recipe-value', (el) => getComputedStyle(el).backgroundColor);

console.log('CONTROL (var(--zimm-color-bg-02), the REAL registered token):', control);
console.log('ACTUAL RECIPE VALUE (var(--zimm-color-background-02), what zimmColourSwatch.css.ts actually uses):', actual);

await browser.close();
EOF
